package fr.formation.clean.interfaceadapter.gateway;
import fr.formation.clean.application.boundary.ReservationGateway;import fr.formation.clean.application.usecase.UseCaseException;import java.time.LocalDateTime;import java.util.UUID;import org.springframework.stereotype.Component;
@Component public class ReservationQuery{private final ReservationGateway gateway;public ReservationQuery(ReservationGateway gateway){this.gateway=gateway;}public View find(UUID id){var r=gateway.findById(id).orElseThrow(()->new UseCaseException("Reservation not found"));return new View(r.id(),r.roomId(),r.organizerEmail(),r.participants(),r.startsAt(),r.endsAt(),r.status().name());}public record View(UUID id,UUID roomId,String organizerEmail,int participants,LocalDateTime startsAt,LocalDateTime endsAt,String status){}}
